1	import { describe, expect, it } from "vitest";
2	import {
3	  createIntelConfig,
4	  createIntelState,
5	  hashState,
6	  intelRules,
7	  replayIntel,
8	  stepIntel,
9	  targetedRumorAvailability,
10	  type IntelConfig,
11	  type IntelMessage,
12	  type IntelMessageBody,
13	  type IntelPoint,
14	  type IntelRubbing,
15	  type IntelState,
16	  type IntelStepResult,
17	  type IntelWorldView,
18	  type RubbingType,
19	  type TargetedRumorRequest,
20	} from "./index.js";
21	
22	const T = 256;
23	const tile = (x: number, y: number): IntelPoint => ({ x: x * T + 128, y: y * T + 128 });
24	/** A 30 × 30 test sea: sector bands are tiles 0–9, 10–19 and 20–29. Islands sit in the four corner sectors. */
25	const MAP = {
26	  widthTiles: 30,
27	  heightTiles: 30,
28	  subUnitsPerTile: T,
29	  islands: [{ name: "Palm Key" }, { name: "Ash Isle" }, { name: "Mist Rock" }, { name: "Old Ruin" }],
30	};
31	const ISLAND_AT = [tile(4, 4), tile(25, 4), tile(4, 25), tile(25, 25)];
32	const ISLAND_SECTOR = [0, 2, 6, 8];
33	/** A point in each of the nine sectors. */
34	const S = [tile(2, 2), tile(15, 2), tile(27, 2), tile(2, 15), tile(15, 15), tile(27, 15), tile(2, 27), tile(15, 27), tile(27, 27)] as const;
35	const FINAL = { x: 15 * T + 7, y: 16 * T + 3 };
36	const START = 100;
37	
38	/** Real reveal times and a 100-tick (5 s) carrier interval, so carrier scenarios stay short. */
39	const quick = createIntelConfig({
40	  preset: "slice",
41	  finalIsland: FINAL,
42	  controlStartTick: START,
43	  map: MAP,
44	  rules: { ...intelRules, carrierIntervalTicks: 100, sightingDelayTicks: 100, sectorRevealTicks: 1_000, carrierRevealTicks: 2_000 },
45	});
46	const real = createIntelConfig({ preset: "slice", finalIsland: FINAL, controlStartTick: START, map: MAP });
47	
48	const typeOf = (id: string) => id.slice(0, id.indexOf("-")) as RubbingType;
49	const source = (id: string, island: number): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "source", island, ...ISLAND_AT[island]! } });
50	const cached = (id: string, at: IntelPoint): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "cache", ...at } });
51	const carried = (id: string, playerId: string): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "carried", playerId } });
52	const reserved = (id: string, playerId: string): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "duel", playerId } });
53	
54	interface World {
55	  readonly players: Readonly<Record<string, IntelPoint>>;
56	  readonly rubbings: readonly IntelRubbing[];
57	}
58	
59	/** Recursively frozen, so a step that mutated its input would throw. */
60	function deepFreeze<T>(value: T): T {
61	  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
62	    Object.freeze(value);
63	    for (const child of Object.values(value)) deepFreeze(child);
64	  }
65	  return value;
66	}
67	
68	function viewOf(tick: number, world: World): IntelWorldView {
69	  return { tick, players: Object.entries(world.players).map(([id, at]) => ({ id, ...at })), rubbings: world.rubbings };
70	}
71	
72	/** Steps with frozen input and state, checking neither changes. */
73	class Run {
74	  state: IntelState;
75	  constructor(
76	    readonly config: IntelConfig,
77	    seed = 1,
78	  ) {
79	    this.state = createIntelState(config, seed);
80	  }
81	
82	  step(tick: number, world: World, requests: TargetedRumorRequest[] = []): IntelStepResult {
83	    const view = deepFreeze(viewOf(tick, world));
84	    const before = hashState(deepFreeze(this.state));
85	    const stepped = stepIntel(this.config, this.state, view, deepFreeze(requests));
86	    expect(hashState(this.state)).toBe(before);
87	    this.state = stepped.state;
88	    return stepped;
89	  }
90	
91	  available(tick: number, world: World, playerId: string, type: RubbingType) {
92	    return targetedRumorAvailability(this.config, this.state, viewOf(tick, world), playerId, type);
93	  }
94	}
95	
96	function to(result: IntelStepResult, playerId: string): IntelMessageBody[] {
97	  return result.messages.filter((message) => message.to.kind === "player" && message.to.playerId === playerId).map((message) => message.body);
98	}
99	
100	function everyone(result: IntelStepResult): IntelMessageBody[] {
101	  return result.messages.filter((message) => message.to.kind === "everyone").map((message) => message.body);
102	}
103	
104	function only<K extends IntelMessageBody["kind"]>(bodies: IntelMessageBody[], kind: K): Extract<IntelMessageBody, { kind: K }> {
105	  const found = bodies.filter((body) => body.kind === kind);
106	  expect(found).toHaveLength(1);
107	  return found[0] as Extract<IntelMessageBody, { kind: K }>;
108	}
109	
110	const request = (requestId: string, playerId: string, type: RubbingType): TargetedRumorRequest => ({ requestId, playerId, type });
111	
112	describe("control start and starting rumors (§2)", () => {
113	  it("say nothing before control start, then give each player a rumor toward a type they lack", () => {
114	    const run = new Run(quick);
115	    const world: World = {
116	      players: { A: S[4], B: S[0], C: S[8] },
117	      rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), source("sun-2", 0), source("moon-2", 1), carried("moon-3", "C")],
118	    };
119	    for (const tick of [0, 50, START - 1]) {
120	      const stepped = run.step(tick, world, [request(`early-${tick}`, "B", "sun")]);
121	      expect(stepped.messages).toEqual([]);
122	      expect(stepped.outcomes).toEqual([{ requestId: `early-${tick}`, result: "none" }]);
123	      expect(run.state.started).toBe(false);
124	    }
125	    const start = run.step(START, world);
126	    expect(run.state.started).toBe(true);
127	    // A already holds a full set: the final sector and route instead of a rumor.
128	    expect(to(start, "A").map((body) => body.kind)).toEqual(["final-route"]);
129	    expect(everyone(start)).toEqual([{ kind: "final-sector", tick: START, sector: 4, name: "Central Waters" }]);
130	    // B lacks both: a rumor for either type, pointing at the island holding it.
131	    const b = only(to(start, "B"), "rumor");
132	    expect(b).toMatchObject({ entry: 1, reason: "start" });
133	    expect(b.target).toEqual(b.type === "sun" ? { kind: "island", island: 0, name: "Palm Key" } : { kind: "island", island: 1, name: "Ash Isle" });
134	    // C holds moon: sun only.
135	    expect(only(to(start, "C"), "rumor")).toEqual({ kind: "rumor", tick: START, entry: 1, type: "sun", reason: "start", target: { kind: "island", island: 0, name: "Palm Key" } });
136	    // A player first seen after control start gets a starting rumor then.
137	    const late = run.step(START + 30, { ...world, players: { ...world.players, D: S[2] } });
138	    expect(only(to(late, "D"), "rumor")).toMatchObject({ reason: "start", tick: START + 30 });
139	    expect(to(late, "B")).toEqual([]);
140	  });
141	
142	  it("give the same rumor for the same seed, and a seed decides between equal targets", () => {
143	    const world: World = { players: { A: S[4] }, rubbings: [source("sun-1", 0), source("sun-2", 1), source("moon-1", 2), source("moon-2", 3)] };
144	    const targetFor = (seed: number) => {
145	      const stepped = new Run(quick, seed).step(START, world);
146	      return only(to(stepped, "A"), "rumor");
147	    };
148	    expect(targetFor(42)).toEqual(targetFor(42));
149	    const seen = new Set(Array.from({ length: 24 }, (_, seed) => JSON.stringify(targetFor(seed))));
150	    expect(seen.size).toBe(4);
151	  });
152	});
153	
154	describe("rumor targets (§3, §11)", () => {
155	  it("prefer a sealed source, then a cache, then a carrier sighting", () => {
156	    const players = { A: S[4], B: S[2] };
157	    const world: World = { players, rubbings: [carried("sun-1", "A"), source("moon-1", 3), cached("moon-2", S[1]), carried("moon-3", "B")] };
158	    let run = new Run(quick);
159	    // The sealed source first…
160	    expect(only(to(run.step(START, world), "A"), "rumor").target).toEqual({ kind: "island", island: 3, name: "Old Ruin" });
161	    // …then, with that island already in the journal, the cache's sector…
162	    const cache = run.step(START + 10, world, [request("r1", "A", "moon")]);
163	    expect(cache.outcomes).toEqual([{ requestId: "r1", result: "rumor" }]);
164	    expect(only(to(cache, "A"), "rumor").target).toEqual({ kind: "sector", sector: 1, name: "Northern Waters" });
165	    // …and no carrier sighting while some copy is not carried.
166	    expect(run.step(START + 20, world, [request("r2", "A", "moon")]).outcomes).toEqual([{ requestId: "r2", result: "none" }]);
167	
168	    run = new Run(quick);
169	    const carrierWorld = (at: IntelPoint): World => ({ players: { A: S[4], B: at }, rubbings: [carried("sun-1", "A"), carried("moon-3", "B")] });
170	    // Every moon is carried: the starting lead is a sighting, which needs a previous snapshot, so it waits a beat.
171	    expect(to(run.step(START, carrierWorld(S[2])), "A")).toEqual([]);
172	    const first = run.step(START + 100, carrierWorld(S[8]));
173	    // The previous snapshot (control start, B in the north-east), not the latest one nor the present.
174	    expect(to(first, "A")).toEqual([
175	      { kind: "carrier-sighting", tick: START + 100, type: "moon", reason: "start", sector: 2, name: "North-East Reach", seenTick: START },
176	    ]);
177	    expect(run.step(START + 150, carrierWorld(S[7]), [request("r3", "A", "moon")]).outcomes).toEqual([{ requestId: "r3", result: "capped" }]);
178	    const bought = run.step(START + 250, carrierWorld(S[7]), [request("r4", "A", "moon")]);
179	    expect(bought.outcomes).toEqual([{ requestId: "r4", result: "sighting" }]);
180	    expect(only(to(bought, "A"), "carrier-sighting")).toMatchObject({ reason: "targeted", sector: 8, seenTick: START + 100 });
181	  });
182	
183	  it("never give a rumor for a held type, nor point a player at their own former copy", () => {
184	    for (let seed = 0; seed < 12; seed++) {
185	      const run = new Run(quick, seed);
186	      const players = { A: S[0], B: S[4], C: S[8] };
187	      // Only two moons: A's and C's. B then steals A's.
188	      const before: World = { players, rubbings: [carried("sun-1", "B"), carried("sun-2", "A"), carried("moon-1", "A"), carried("moon-2", "C")] };
189	      run.step(START, before);
190	      const held = run.step(START + 10, before, [
191	        request("held", "A", "moon"),
192	      ]);
193	      expect(held.outcomes).toEqual([{ requestId: "held", result: "none" }]);
194	      expect(to(held, "A")).toEqual([]);
195	      const stolen: World = { players: { ...players, B: S[2] }, rubbings: [carried("sun-1", "B"), carried("sun-2", "A"), carried("moon-1", "B"), carried("moon-2", "C")] };
196	      // The fresh rumor finds every moon carried and no previous snapshot yet: it waits for the next boundary.
197	      expect(to(run.step(START + 50, stolen), "A")).toEqual([{ kind: "final-route-inactive", tick: START + 50 }]);
198	      const delivered = run.step(START + 100, stolen);
199	      // The previous snapshot (tick 100) has A's own moon in the north-west and C's in the south-east: never A's own.
200	      expect(only(to(delivered, "A"), "carrier-sighting")).toMatchObject({ type: "moon", reason: "fresh", sector: 8, seenTick: START });
201	    }
202	  });
203	});
204	
205	describe("losses (§11)", () => {
206	  it("give a free fresh rumor when a type is stolen, and nothing when a rubbing is only reserved in a duel", () => {
207	    const run = new Run(quick);
208	    const players = { A: S[4], B: S[5] };
209	    const others = [source("sun-2", 0), source("moon-1", 1)];
210	    const start = run.step(START, { players, rubbings: [carried("sun-1", "A"), ...others] });
211	    expect(only(to(start, "B"), "rumor")).toBeDefined();
212	    const duel = run.step(START + 5, { players, rubbings: [reserved("sun-1", "A"), ...others] });
213	    expect(duel.messages).toEqual([]);
214	    const theft = run.step(START + 6, { players, rubbings: [carried("sun-1", "B"), ...others] });
215	    expect(only(to(theft, "A"), "rumor")).toEqual({
216	      kind: "rumor",
217	      tick: START + 6,
218	      entry: 2,
219	      type: "sun",
220	      reason: "fresh",
221	      target: { kind: "island", island: 0, name: "Palm Key" },
222	    });
223	  });
224	
225	  it("keep a fresh sighting waiting while no snapshot shows another carrier, and send a no-lead when no copy is left", () => {
226	    // After the theft only the thief carries sun, and the thief was not carrying it at any snapshot: the fresh
227	    // rumor waits, and at the next boundary the previous snapshot still lacks the thief, so it keeps waiting.
228	    const run = new Run(quick);
229	    const players = { A: S[4], B: S[5] };
230	    run.step(START, { players, rubbings: [carried("sun-1", "A")] });
231	    run.step(START + 20, { players, rubbings: [carried("sun-1", "B")] });
232	    expect(to(run.step(START + 100, { players, rubbings: [carried("sun-1", "B")] }), "A")).toEqual([]);
233	    expect(run.state.players.find((player) => player.id === "A")!.pending).toEqual([{ type: "sun", reason: "fresh", tick: START + 20 }]);
234	    const later = run.step(START + 200, { players, rubbings: [carried("sun-1", "B")] });
235	    expect(only(to(later, "A"), "carrier-sighting")).toMatchObject({ type: "sun", sector: 5, seenTick: START + 100 });
236	    // With no copy of a type left in the view at all, a stale rumor's replacement is a no-lead.
237	    const empty = new Run(quick);
238	    empty.step(START, { players, rubbings: [source("moon-1", 1), carried("sun-1", "A")] });
239	    const gone = empty.step(START + 5, { players, rubbings: [carried("sun-1", "A")] });
240	    expect(to(gone, "A").map((body) => body.kind)).toEqual(["rumor-stale", "no-lead"]);
241	  });
242	});
