244	describe("staleness and the journal (§3)", () => {
245	  it("mark an island rumor stale when another player collects its source, and offer a remaining source", () => {
246	    const run = new Run(quick, 3);
247	    const players = { A: S[4], B: S[1] };
248	    const moons = [source("moon-1", 1), source("moon-2", 3)];
249	    const start = only(to(run.step(START, { players, rubbings: [carried("sun-1", "A"), ...moons] }), "A"), "rumor");
250	    expect(start.target.kind).toBe("island");
251	    const island = start.target.kind === "island" ? start.target.island : -1;
252	    const taken = island === 1 ? "moon-1" : "moon-2";
253	    const rest = moons.filter((rubbing) => rubbing.id !== taken);
254	    const collected = run.step(START + 40, { players, rubbings: [carried("sun-1", "A"), carried(taken, "B"), ...rest] });
255	    expect(to(collected, "A")).toEqual([
256	      { kind: "rumor-stale", tick: START + 40, entry: 1, type: "moon" },
257	      {
258	        kind: "rumor",
259	        tick: START + 40,
260	        entry: 2,
261	        type: "moon",
262	        reason: "replacement",
263	        target: { kind: "island", island: island === 1 ? 3 : 1, name: island === 1 ? "Old Ruin" : "Ash Isle" },
264	      },
265	    ]);
266	    expect(run.state.players.find((player) => player.id === "A")!.journal.map((rumor) => [rumor.entry, rumor.status, rumor.closedTick])).toEqual([
267	      [1, "stale", START + 40],
268	      [2, "active", null],
269	    ]);
270	  });
271	
272	  it("keep an island rumor while another copy of its type is still sealed there", () => {
273	    const run = new Run(quick);
274	    const players = { A: S[4], B: S[1] };
275	    run.step(START, { players, rubbings: [carried("sun-1", "A"), source("moon-1", 1), source("moon-2", 1)] });
276	    expect(to(run.step(START + 1, { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "B"), source("moon-2", 1)] }), "A")).toEqual([]);
277	  });
278	
279	  it("mark a cache rumor stale when its cache is claimed, and offer the remaining cache", () => {
280	    const run = new Run(quick, 5);
281	    const players = { A: S[4], C: S[0] };
282	    const caches = [cached("sun-1", S[1]), cached("sun-2", S[7])];
283	    const start = only(to(run.step(START, { players, rubbings: [carried("moon-1", "A"), ...caches] }), "A"), "rumor");
284	    const sector = start.target.kind === "sector" ? start.target.sector : -1;
285	    expect([1, 7]).toContain(sector);
286	    const claimed = sector === 1 ? "sun-1" : "sun-2";
287	    const claim = run.step(START + 60, { players, rubbings: [carried("moon-1", "A"), carried(claimed, "C"), ...caches.filter((rubbing) => rubbing.id !== claimed)] });
288	    expect(to(claim, "A")).toEqual([
289	      { kind: "rumor-stale", tick: START + 60, entry: 1, type: "sun" },
290	      { kind: "rumor", tick: START + 60, entry: 2, type: "sun", reason: "replacement", target: { kind: "sector", sector: sector === 1 ? 7 : 1, name: sector === 1 ? "Southern Waters" : "Northern Waters" } },
291	    ]);
292	  });
293	
294	  it("resolve a rumor quietly when its holder obtains the type, by collection or by theft", () => {
295	    const players = { A: S[4], B: S[3] };
296	    // Collection: A empties the very island the rumor names; that is resolved, not stale.
297	    let run = new Run(quick);
298	    run.step(START, { players, rubbings: [carried("sun-1", "A"), source("moon-1", 1)] });
299	    expect(to(run.step(START + 120, { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "A")] }), "A")).toEqual([
300	      { kind: "rumor-resolved", tick: START + 120, entry: 1, type: "moon" },
301	      { kind: "final-route", tick: START + 120, x: FINAL.x, y: FINAL.y, restored: false },
302	    ]);
303	    // Theft: A wins B's moon while B, on the same tick, collects the island A's rumor names.
304	    run = new Run(quick);
305	    run.step(START, { players, rubbings: [carried("sun-1", "A"), carried("moon-2", "B"), source("moon-1", 1)] });
306	    const stolen = run.step(START + 9, { players, rubbings: [carried("sun-1", "A"), carried("moon-2", "A"), carried("moon-1", "B")] });
307	    expect(to(stolen, "A").filter((body) => body.kind.startsWith("rumor"))).toEqual([{ kind: "rumor-resolved", tick: START + 9, entry: 1, type: "moon" }]);
308	    expect(run.state.players.find((player) => player.id === "A")!.journal[0]!.status).toBe("resolved");
309	  });
310	
311	  it("replace a stale rumor with a sighting from the previous snapshot when every remaining copy is carried", () => {
312	    const run = new Run(quick, 9);
313	    const world = (tick: number, c: IntelPoint, b: IntelPoint, bHasMoon: boolean): World => ({
314	      players: { A: S[4], B: b, C: c },
315	      rubbings: [carried("sun-1", "A"), carried("moon-2", "C"), bHasMoon ? carried("moon-1", "B") : source("moon-1", 1)],
316	    });
317	    expect(only(to(run.step(START, world(START, S[3], S[0], false)), "A"), "rumor").target).toMatchObject({ kind: "island", island: 1 });
318	    run.step(START + 100, world(START + 100, S[6], S[0], false));
319	    run.step(START + 200, world(START + 200, S[7], S[0], false));
320	    const emptied = run.step(START + 250, world(START + 250, S[8], S[2], true));
321	    expect(to(emptied, "A")).toEqual([
322	      { kind: "rumor-stale", tick: START + 250, entry: 1, type: "moon" },
323	      // C was in the south-west at the previous snapshot (tick 200 is the latest; tick 100 the previous one), never now.
324	      { kind: "carrier-sighting", tick: START + 250, type: "moon", reason: "replacement", sector: 6, name: "South-West Reach", seenTick: START + 100 },
325	    ]);
326	    // A carrier sighting is one-shot: C moving on, or B's moon moving, never makes it stale.
327	    const moved = run.step(START + 260, { players: { A: S[4], B: S[5], C: S[1] }, rubbings: [carried("sun-1", "A"), carried("moon-2", "B"), carried("moon-1", "C")] });
328	    expect(to(moved, "A")).toEqual([]);
329	  });
330	
331	  it("defer a capped free sighting to the next snapshot boundary instead of dropping it", () => {
332	    const run = new Run(quick, 2);
333	    const world = (sunAtSource: boolean, cAt: IntelPoint = S[1]): World => ({
334	      players: { A: S[4], B: S[0], C: cAt, D: S[5] },
335	      rubbings: [carried("sun-1", "C"), sunAtSource ? source("sun-2", 0) : carried("sun-2", "B"), carried("moon-1", "D")],
336	    });
337	    // A lacks both; only sun has a source, so the start rumor names Palm Key.
338	    expect(only(to(run.step(START, world(true)), "A"), "rumor")).toMatchObject({ type: "sun", target: { kind: "island", island: 0 } });
339	    run.step(START + 100, world(true, S[3]));
340	    const bought = run.step(START + 150, world(true, S[3]), [request("moon-buy", "A", "moon")]);
341	    expect(bought.outcomes).toEqual([{ requestId: "moon-buy", result: "sighting" }]);
342	    expect(only(to(bought, "A"), "carrier-sighting")).toMatchObject({ type: "moon", sector: 5, seenTick: START });
343	    // B collects the last sealed sun: the rumor goes stale, every sun is carried, and A's sighting for this snapshot is spent.
344	    const stale = run.step(START + 160, world(false, S[3]));
345	    expect(to(stale, "A")).toEqual([{ kind: "rumor-stale", tick: START + 160, entry: 1, type: "sun" }]);
346	    expect(run.state.players.find((player) => player.id === "A")!.pending).toEqual([{ type: "sun", reason: "replacement", tick: START + 160 }]);
347	    expect(run.step(START + 170, world(false, S[3]), [request("sun-buy", "A", "sun")]).outcomes).toEqual([{ requestId: "sun-buy", result: "capped" }]);
348	    expect(to(run.step(START + 199, world(false, S[8])), "A")).toEqual([]);
349	    const next = run.step(START + 200, world(false, S[8]));
350	    // Delivered at the boundary from the previous snapshot (tick 100): C was in the west; B had not collected yet.
351	    expect(to(next, "A")).toEqual([
352	      { kind: "carrier-sighting", tick: START + 200, type: "sun", reason: "replacement", sector: 3, name: "Western Waters", seenTick: START + 100 },
353	    ]);
354	    expect(run.state.players.find((player) => player.id === "A")!.pending).toEqual([]);
355	  });
356	});
