80	  { name: "quick, slice, seed 2", seed: 2, preset: "slice", realTimes: false, endTick: 3_400, skipPerMille: 0 },
81	  { name: "quick, alpha, seed 3", seed: 3, preset: "alpha", realTimes: false, endTick: 3_400, skipPerMille: 0 },
82	  { name: "quick, slice, skipping, seed 4", seed: 4, preset: "slice", realTimes: false, endTick: 3_400, skipPerMille: 300 },
83	  { name: "quick, alpha, skipping, seed 5", seed: 5, preset: "alpha", realTimes: false, endTick: 3_400, skipPerMille: 300 },
84	  { name: "real times, alpha, skipping, seed 6", seed: 6, preset: "alpha", realTimes: true, endTick: START + 36_000, skipPerMille: 500 },
85	];
86	
87	interface SimPlayer {
88	  x: number;
89	  y: number;
90	  heading: number;
91	}
92	
93	const DIRECTIONS = [
94	  [1, 0],
95	  [1, 1],
96	  [0, 1],
97	  [-1, 1],
98	  [-1, 0],
99	  [-1, -1],
100	  [0, -1],
101	  [1, -1],
102	] as const;
103	
104	/**
105	 * A seeded match seen from outside: ships sail and turn, players collect sealed sources and claim caches, fight duels
106	 * (reserving their rubbings) that end in a theft or a draw, leave (their rubbings go into a cache where they were)
107	 * and join, and buy targeted rumors, sometimes repeating a request id. Some scenarios jump several ticks at once.
108	 */
109	function randomScript(scenario: Scenario, config: IntelConfig, map: IntelMapShape): IntelReplayTick[] {
110	  const draw = generator(scenario.seed);
111	  const chance = (perMille: number) => draw(1000) < perMille;
112	  const preset = rulesPresets[scenario.preset];
113	  const width = map.widthTiles * T;
114	  const height = map.heightTiles * T;
115	  const players = new Map<string, SimPlayer>();
116	  let nextPlayer = 0;
117	  const join = () => {
118	    players.set(`crew-${nextPlayer++}`, { x: draw(width), y: draw(height), heading: draw(8) });
119	  };
120	  for (let index = 0; index < preset.maxPlayers; index++) join();
121	  const rubbings = new Map<string, IntelRubbing>();
122	  const deck = presetRubbings(preset);
123	  deck.forEach((rubbing, index) => {
124	    const island = Math.floor(index / preset.sourcesPerIsland);
125	    // Spread each type over the islands: deal by a seeded shuffle of the deck positions.
126	    rubbings.set(rubbing.id, { id: rubbing.id, type: rubbing.type, place: { kind: "source", island, ...islandPoint(map, island) } });
127	  });
128	  // Shuffle which type sits on which island.
129	  const ids = [...rubbings.keys()];
130	  for (let index = ids.length - 1; index > 0; index--) {
131	    const other = draw(index + 1);
132	    const a = rubbings.get(ids[index]!)!;
133	    const b = rubbings.get(ids[other]!)!;
134	    rubbings.set(a.id, { ...a, place: b.place });
135	    rubbings.set(b.id, { ...b, place: a.place });
136	  }
137	  const duels: { a: string; b: string; until: number }[] = [];
138	  const inDuel = (id: string) => duels.some((duel) => duel.a === id || duel.b === id);
139	  const heldTypes = (id: string) =>
140	    [...rubbings.values()].filter((rubbing) => (rubbing.place.kind === "carried" || rubbing.place.kind === "duel") && rubbing.place.playerId === id).map((rubbing) => rubbing.type);
141	  const pick = <T>(items: readonly T[]): T | undefined => (items.length === 0 ? undefined : items[draw(items.length)]);
142	  const requestIds: string[] = [];
143	
144	  const script: IntelReplayTick[] = [];
145	  let tick = 0;
146	  while (tick < scenario.endTick) {
147	    const dt = chance(scenario.skipPerMille) ? 2 + draw(39) : 1;
148	    tick += dt;
149	    for (const player of players.values()) {
150	      if (chance(15)) player.heading = draw(8);
151	      const [dx, dy] = DIRECTIONS[player.heading]!;
152	      player.x = Math.min(Math.max(player.x + dx * 64 * dt, 0), width - 1);
153	      player.y = Math.min(Math.max(player.y + dy * 64 * dt, 0), height - 1);
154	      if (player.x === 0 || player.y === 0 || player.x === width - 1 || player.y === height - 1) player.heading = draw(8);
155	    }
156	    const free = [...players.keys()].filter((id) => !inDuel(id));
157	    // Collect a sealed source of a missing type; the ship is then at that island.
158	    if (chance(8)) {
159	      const id = pick(free);
160	      if (id !== undefined) {
161	        const held = heldTypes(id);
162	        const target = pick([...rubbings.values()].filter((rubbing) => rubbing.place.kind === "source" && !held.includes(rubbing.type)));
163	        if (target !== undefined && target.place.kind === "source") {
164	          const player = players.get(id)!;
165	          player.x = target.place.x;
166	          player.y = target.place.y;
167	          rubbings.set(target.id, { ...target, place: { kind: "carried", playerId: id } });
168	        }
169	      }
170	    }
171	    // Claim a cached copy of a missing type.
172	    if (chance(10)) {
173	      const id = pick(free);
174	      if (id !== undefined) {
175	        const held = heldTypes(id);
176	        const target = pick([...rubbings.values()].filter((rubbing) => rubbing.place.kind === "cache" && !held.includes(rubbing.type)));
177	        if (target !== undefined) rubbings.set(target.id, { ...target, place: { kind: "carried", playerId: id } });
178	      }
179	    }
180	    // Duels reserve both inventories and end in a theft or a draw.
181	    for (const duel of duels.filter((candidate) => candidate.until <= tick)) {
182	      duels.splice(duels.indexOf(duel), 1);
183	      for (const rubbing of rubbings.values()) {
184	        if (rubbing.place.kind === "duel") rubbings.set(rubbing.id, { ...rubbing, place: { kind: "carried", playerId: rubbing.place.playerId } });
185	      }
186	      if (chance(850)) {
187	        const [winner, loser] = chance(500) ? [duel.a, duel.b] : [duel.b, duel.a];
188	        const winnerTypes = heldTypes(winner);
189	        const stolen = pick(
190	          [...rubbings.values()].filter(
191	            (rubbing) => rubbing.place.kind === "carried" && rubbing.place.playerId === loser && !winnerTypes.includes(rubbing.type),
192	          ),
193	        );
194	        if (stolen !== undefined) rubbings.set(stolen.id, { ...stolen, place: { kind: "carried", playerId: winner } });
195	      }
196	      for (const rubbing of rubbings.values()) {
197	        const place = rubbing.place;
198	        if (place.kind === "carried" && inDuel(place.playerId)) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "duel", playerId: place.playerId } });
199	      }
200	    }
201	    if (chance(12)) {
202	      const a = pick(free);
203	      const b = pick(free.filter((id) => id !== a));
204	      if (a !== undefined && b !== undefined) {
205	        duels.push({ a, b, until: tick + 20 + draw(80) });
206	        for (const rubbing of rubbings.values()) {
207	          const place = rubbing.place;
208	          if (place.kind === "carried" && (place.playerId === a || place.playerId === b)) {
209	            rubbings.set(rubbing.id, { ...rubbing, place: { kind: "duel", playerId: place.playerId } });
210	          }
211	        }
212	      }
213	    }
214	    // Leaving drops everything into a cache where the ship was; someone new may join.
215	    if (chance(2) && players.size > 2) {
216	      const id = pick(free);
217	      if (id !== undefined) {
218	        const player = players.get(id)!;
219	        for (const rubbing of rubbings.values()) {
220	          if (rubbing.place.kind === "carried" && rubbing.place.playerId === id) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "cache", x: player.x, y: player.y } });
221	        }
222	        players.delete(id);
223	      }
224	    }
225	    if (chance(2) && players.size < preset.maxPlayers) join();
226	
227	    const requests: TargetedRumorRequest[] = [];
228	    if (tick > config.controlStartTick - 20 && chance(15)) {
229	      const playerId = pick([...players.keys(), "nobody"])!;
230	      const reuse = requestIds.length > 0 && chance(250);
231	      const requestId = reuse ? requestIds[draw(requestIds.length)]! : `req-${requestIds.length}`;
232	      if (!reuse) requestIds.push(requestId);
233	      requests.push({ requestId, playerId, type: config.types[draw(config.types.length)]! });
234	    }
235	    const view: IntelWorldView = {
236	      tick,
237	      players: [...players].map(([id, player]) => ({ id, x: player.x, y: player.y })),
238	      rubbings: [...rubbings.values()],
239	    };
240	    script.push(deepFreeze({ view, requests }));
241	  }
242	  return script;
243	}
244	
245	/** What a view says, for checking messages against it. */
246	interface Facts {
247	  readonly players: ReadonlySet<string>;
248	  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
249	  readonly sourceIslands: readonly { type: RubbingType; island: number }[];
250	  readonly cacheSectors: readonly { type: RubbingType; sector: number }[];
251	  readonly carriers: readonly { type: RubbingType; sector: number; holder: string }[];
252	}
253	
254	function factsOf(config: IntelConfig, view: IntelWorldView): Facts {
255	  const positions = new Map(view.players.map((player) => [player.id, player]));
256	  const held = new Map<string, RubbingType[]>(view.players.map((player) => [player.id, []]));
257	  const sourceIslands: { type: RubbingType; island: number }[] = [];
258	  const cacheSectors: { type: RubbingType; sector: number }[] = [];
259	  const carriers: { type: RubbingType; sector: number; holder: string }[] = [];
260	  for (const rubbing of view.rubbings) {
261	    const place = rubbing.place;
262	    if (place.kind === "source") sourceIslands.push({ type: rubbing.type, island: place.island });
263	    else if (place.kind === "cache") cacheSectors.push({ type: rubbing.type, sector: sectorOf(config, place) });
264	    else {
265	      held.get(place.playerId)!.push(rubbing.type);
266	      carriers.push({ type: rubbing.type, sector: sectorOf(config, positions.get(place.playerId)!), holder: place.playerId });
267	    }
268	  }
269	  return { players: new Set(positions.keys()), held, sourceIslands, cacheSectors, carriers };
270	}
271	
272	/** The keys each message kind may carry: none is an id, and only `final-route` has a position. */
273	const BODY_KEYS: Record<IntelMessageKind, readonly string[]> = {
274	  rumor: ["entry", "kind", "reason", "target", "tick", "type"],
275	  "carrier-sighting": ["kind", "name", "reason", "sector", "seenTick", "tick", "type"],
276	  "no-lead": ["kind", "reason", "tick", "type"],
277	  "rumor-stale": ["entry", "kind", "tick", "type"],
278	  "rumor-resolved": ["entry", "kind", "tick", "type"],
279	  "final-sector": ["kind", "name", "sector", "tick"],
280	  "final-route": ["kind", "restored", "tick", "x", "y"],
281	  "final-route-inactive": ["kind", "tick"],
282	  "sector-reveal": ["caches", "kind", "sources", "tick"],
283	  "carrier-report": ["carriers", "kind", "seenTick", "tick"],
284	};
285	const BROADCASTS: ReadonlySet<IntelMessageKind> = new Set(["final-sector", "sector-reveal", "carrier-report"]);
286	const NESTED_KEYS = new Set(["kind", "island", "sector", "name", "type"]);
287	
288	/** Every kind, outcome and path the property runs must reach, filled as they run. */
289	const EXERCISED = new Set<string>();
290	const MUST_EXERCISE = [
291	  ...Object.keys(BODY_KEYS).map((kind) => `message:${kind}`),
292	  ...(["rumor", "sighting", "capped", "none", "duplicate"] satisfies TargetedRumorResult[]).map((result) => `outcome:${result}`),
293	  ...["start", "fresh", "targeted", "replacement"].map((reason) => `rumor:${reason}`),
294	  ...["fresh", "targeted", "replacement"].map((reason) => `sighting:${reason}`),
295	  "rumor:island",
296	  "rumor:sector",
297	  "route:restored",
298	  "sighting:deferred",
299	  "skipped-ticks",
300	];
301	
302	function allStrings(value: unknown, out: string[] = []): string[] {
303	  if (typeof value === "string") out.push(value);
304	  else if (Array.isArray(value)) for (const item of value) allStrings(item, out);
305	  else if (typeof value === "object" && value !== null) for (const item of Object.values(value)) allStrings(item, out);
306	  return out;
307	}
308	
309	/**
310	 * Checks every message of a run against the design's rules (§3, §5, §11, §16), with the views that produced them. It
311	 * returns nothing and throws on the first violation, with the tick and message.
312	 */
313	class Checker {
314	  private readonly rumors = new Map<string, { type: RubbingType; closed: boolean; target: unknown }>();
315	  private readonly sightings = new Map<string, number>();
316	  private readonly carriersAt = new Map<number, Facts["carriers"]>();
317	  private readonly ids = new Set<string>();
318	  private previousTick = -Infinity;
319	
320	  constructor(
321	    private readonly config: IntelConfig,
322	    private readonly skipping: boolean,
323	  ) {}
324	
325	  check(view: IntelWorldView, messages: readonly IntelMessage[], state: IntelState): void {
326	    const config = this.config;
327	    const tick = view.tick;
328	    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
329	    this.previousTick = tick;
330	    const facts = factsOf(config, view);
331	    this.carriersAt.set(tick, facts.carriers);
332	    for (const player of view.players) this.ids.add(player.id);
333	    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
334	    if (state.players.some((player) => player.pending.length > 0)) EXERCISED.add("sighting:deferred");
335	    const fail = (message: IntelMessage, why: string): never => {
336	      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
337	    };
338	    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
339	    for (const message of messages) {
340	      const body = message.body;
341	      EXERCISED.add(`message:${body.kind}`);
342	      if (body.tick !== tick) fail(message, "wrong tick");
343	      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
344	      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
345	      for (const nested of ["target", "sources", "caches", "carriers"] as const) {
346	        const value = (body as Record<string, unknown>)[nested];
347	        if (value === undefined) continue;
348	        for (const item of Array.isArray(value) ? value : [value]) {
349	          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
350	        }
351	      }
352	      // No id anywhere in a body.
353	      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
354	      // Addressing: broadcasts to everyone, everything else to one player present now.
355	      if (BROADCASTS.has(body.kind)) {
356	        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
357	        continue;
358	      }
359	      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
360	      const recipient = (message.to as { playerId: string }).playerId;
361	      const held = facts.held.get(recipient)!;
362	      const complete = config.types.every((type) => held.includes(type));
363	      const key = (entry: number) => `${recipient}#${entry}`;
364	      switch (body.kind) {
365	        case "final-route":
366	          // The only exact position ever sent, and only to a full-set holder.
367	          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
368	          if (body.restored) EXERCISED.add("route:restored");
369	          break;
370	        case "final-route-inactive":
371	          if (complete) fail(message, "a route suspended for a full set");
372	          break;
373	        case "rumor": {
374	          EXERCISED.add(`rumor:${body.reason}`);
375	          EXERCISED.add(`rumor:${body.target.kind}`);
376	          if (held.includes(body.type)) fail(message, "a rumor for a held type");
377	          const target = body.target;
378	          const there =
379	            target.kind === "island"
380	              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
381	              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
382	          if (!there) fail(message, "a rumor pointing at nothing");
383	          if (this.rumors.has(key(body.entry))) fail(message, "a journal entry reused");
384	          this.rumors.set(key(body.entry), { type: body.type, closed: false, target });
385	          break;
386	        }
387	        case "rumor-stale":
388	        case "rumor-resolved": {
389	          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
390	          const rumor = this.rumors.get(key(body.entry));
391	          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
392	          rumor!.closed = true;
393	          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
394	          if (body.kind === "rumor-stale") {
395	            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
396	            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
397	            const there =
398	              target.kind === "island"
399	                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
400	                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
401	            if (there) fail(message, "stale while the target still holds the type");
402	          }
403	          break;
404	        }
405	        case "carrier-sighting": {
406	          EXERCISED.add(`sighting:${body.reason}`);
407	          if (held.includes(body.type)) fail(message, "a sighting for a held type");
408	          if (body.seenTick >= tick) fail(message, "a sighting of the present");
409	          const age = tick - body.seenTick;
410	          const interval = config.carrierIntervalTicks;
411	          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
412	          const then = this.carriersAt.get(body.seenTick);
413	          if (then === undefined) fail(message, "a sighting of a tick never seen");
414	          if (!then!.some((carrier) => carrier.type === body.type && carrier.sector === body.sector && carrier.holder !== recipient)) {
415	            fail(message, "a sighting of no other carrier");
416	          }
417	          if (tick < config.carrierRevealTick) {
418	            const snapshot = `${recipient}@${Math.floor((tick - config.controlStartTick) / interval)}`;
419	            const count = (this.sightings.get(snapshot) ?? 0) + 1;
420	            if (count > 1) fail(message, "a second sighting in one snapshot");
421	            this.sightings.set(snapshot, count);
422	          }
423	          break;
424	        }
425	        case "no-lead":
426	          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
427	          break;
428	      }
429	    }
430	  }
431	}
432	
433	function setup(scenario: Scenario) {
434	  const map = scenario.preset === "slice" ? SLICE_MAP : ALPHA_MAP;
435	  const config = createIntelConfig({
436	    preset: scenario.preset,
437	    finalIsland: { x: (map.widthTiles * T) >> 1, y: ((map.heightTiles * T) >> 1) + 77 },
438	    controlStartTick: START,
439	    map,
440	    ...(scenario.realTimes ? {} : { rules: QUICK_RULES }),
441	  });
442	  return { config, script: randomScript(scenario, config, map) };
443	}
444	
445	describe("intel property runs (§3, §5, §11, §16)", () => {
446	  for (const scenario of SCENARIOS) {
447	    it(`keep every message within the rules: ${scenario.name}`, { timeout: 120_000 }, () => {
448	      const { config, script } = setup(scenario);
449	      if (scenario.realTimes && scenario.skipPerMille === 0) {
450	        expect(config.carrierIntervalTicks).toBe(600);
451	        expect(script.at(-1)!.view.tick - config.controlStartTick).toBeGreaterThanOrEqual(36_000);
452	        expect(script.at(-1)!.view.tick).toBeGreaterThan(config.carrierRevealTick + 4 * config.carrierIntervalTicks);
453	      }
454	      const checker = new Checker(config, scenario.skipPerMille > 0);
455	      let state = createIntelState(config, scenario.seed);
456	      const kinds = new Set<string>();
457	      const messages: IntelMessage[] = [];
458	      for (const { view, requests } of script) {
459	        // Frozen (views are frozen too), so a step that wrote into its input would throw.
460	        const stepped = stepIntel(config, deepFreeze(state), view, requests ?? []);
461	        messages.push(...stepped.messages);
462	        expect(stepped.outcomes.map((outcome) => outcome.requestId)).toEqual((requests ?? []).map((request) => request.requestId));
463	        for (const outcome of stepped.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
464	        checker.check(view, stepped.messages, stepped.state);
465	        for (const message of stepped.messages) kinds.add(message.body.kind);
466	        state = stepped.state;
467	      }
468	      // The run reached the reveals it spans.
469	      expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
470	      // Replaying the same script from the same seed reaches the same state.
471	      const replayed = replayIntel(config, createIntelState(config, scenario.seed), script);
472	      expect(replayed.hash).toBe(hashState(state));
473	      expect(replayed.messages).toEqual(messages);
474	    });
475	  }
476	
477	  it("exercise every message kind, outcome and lead path (EXERCISED)", () => {
478	    expect(MUST_EXERCISE.filter((path) => !EXERCISED.has(path))).toEqual([]);
479	  });
480	});
481

