304	
305	  if (tick < config.controlStartTick) {
306	    for (const { index } of accepted) outcomes.set(index, "none");
307	    for (const player of players) player.held = world.held.get(player.id)!;
308	    return { state: { ...state, tick, players: players.map(frozen), requestIds }, messages, outcomes: answer() };
309	  }
310	
311	  // 1. Carrier snapshots.
312	  let snapshots = state.snapshots;
313	  const boundary = boundaryIndex(tick, config.controlStartTick, config.carrierIntervalTicks);
314	  const crossedBoundary = boundary > (snapshots.at(-1)?.boundary ?? -1);
315	  if (crossedBoundary) snapshots = [...snapshots, { boundary, tick, entries: world.carriers }].slice(-2);
316	
317	  const deliverRumor = (player: WorkingPlayer, plan: Extract<LeadPlan, { kind: "journal" }>, reason: IntelLeadReason): void => {
318	    const { type, target } = plan.options[draw(plan.options.length)]!;
319	    const entry = player.journal.length + 1;
320	    player.journal.push({ entry, type, target, reason, tick, status: "active", closedTick: null });
321	    toPlayer(player.id, {
322	      kind: "rumor",
323	      tick,
324	      entry,
325	      type,
326	      reason,
327	      target:
328	        target.kind === "island"
329	          ? { kind: "island", island: target.island, name: config.islandNames[target.island]! }
330	          : { kind: "sector", sector: target.sector, name: sectorName(config, target.sector) },
331	    });
332	  };
333	  const deliverSighting = (player: WorkingPlayer, plan: Extract<LeadPlan, { kind: "carrier" }>, reason: IntelLeadReason): void => {
334	    const { type, sector } = plan.options[draw(plan.options.length)]!;
335	    player.lastSightingBoundary = snapshots.at(-1)!.boundary;
336	    toPlayer(player.id, { kind: "carrier-sighting", tick, type, reason, sector, name: sectorName(config, sector), seenTick: plan.seenTick });
337	  };
338	  /** A free lead (start, loss or journal replacement): a capped or data-less sighting waits for the next boundary. */
339	  const freeLead = (player: WorkingPlayer, types: readonly RubbingType[], reason: PendingSighting["reason"]): void => {
340	    const plan = planLead(config, world, snapshots, player, types);
341	    if (plan.kind === "journal") return deliverRumor(player, plan, reason);
342	    if (plan.kind === "carrier") {
343	      if (!plan.capped && plan.options.length > 0) return deliverSighting(player, plan, reason);
344	      for (const type of plan.types) if (!player.pending.some((pending) => pending.type === type)) player.pending.push({ type, reason, tick });
