346	    }
347	    const lacking = config.types.filter((type) => types.includes(type) && !(world.held.get(player.id) ?? []).includes(type));
348	    if (lacking.length > 0) toPlayer(player.id, { kind: "no-lead", tick, type: lacking[0]!, reason });
349	  };
350	
351	  // 2. Players.
352	  const startCrossed = !state.started;
353	  let finalAnnounced = state.finalSectorAnnounced;
354	  for (const player of players) {
355	    const held = world.held.get(player.id)!;
356	    if (startCrossed || !previous.has(player.id)) {
357	      player.held = held;
358	      freeLead(player, config.types, "start");
359	    } else {
