430	    outcomes.set(index, result);
431	  }
432	
433	  // 4. Timed reveals (§2).
434	  let sectorRevealed = state.sectorRevealed;
435	  if (!sectorRevealed && tick >= config.sectorRevealTick) {
436	    sectorRevealed = true;
437	    toEveryone({
438	      kind: "sector-reveal",
439	      tick,
440	      sources: uniqueSorted(world.sources.map((source) => source.sector)).map((sector) => sectorRef(config, sector)),
441	      caches: uniqueSorted(world.caches.map((cache) => cache.sector)).map((sector) => sectorRef(config, sector)),
