449	    const carriers: (SectorRef & { type: RubbingType })[] = [];
450	    for (const entry of newest.entries) {
451	      if (!carriers.some((carrier) => carrier.sector === entry.sector && carrier.type === entry.type)) {
452	        carriers.push({ ...sectorRef(config, entry.sector), type: entry.type });
453	      }
454	    }
455	    toEveryone({ kind: "carrier-report", tick, seenTick: newest.tick, carriers });
456	  }
457	
458	  return {
459	    state: {

